PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'player' CHECK(role IN ('player','creator','admin')),avatar_url TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS creator_profiles(id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,display_name TEXT NOT NULL,biography TEXT DEFAULT '',social_links TEXT DEFAULT '{}',verification_status TEXT NOT NULL DEFAULT 'unverified',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE,icon TEXT,description TEXT,active INTEGER NOT NULL DEFAULT 1,display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS mods(id TEXT PRIMARY KEY,creator_id TEXT NOT NULL REFERENCES users(id),category_id INTEGER REFERENCES categories(id),title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL,thumbnail_url TEXT,version TEXT NOT NULL,minecraft_versions TEXT NOT NULL DEFAULT '[]',tags TEXT NOT NULL DEFAULT '[]',credits TEXT NOT NULL DEFAULT '',license TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending_review','under_review','changes_requested','approved','rejected','published','suspended','archived')),moderation_feedback TEXT,download_count INTEGER NOT NULL DEFAULT 0,featured INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TEXT);
CREATE TABLE IF NOT EXISTS mod_files(id TEXT PRIMARY KEY,mod_id TEXT NOT NULL REFERENCES mods(id) ON DELETE CASCADE,storage_key TEXT NOT NULL UNIQUE,file_name TEXT NOT NULL,file_type TEXT NOT NULL,file_size INTEGER NOT NULL,file_version TEXT NOT NULL,scan_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mod_images(id TEXT PRIMARY KEY,mod_id TEXT NOT NULL REFERENCES mods(id) ON DELETE CASCADE,image_url TEXT NOT NULL,display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS favorites(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,mod_id TEXT NOT NULL REFERENCES mods(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,mod_id));
CREATE TABLE IF NOT EXISTS downloads(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),mod_id TEXT NOT NULL REFERENCES mods(id),file_id TEXT NOT NULL REFERENCES mod_files(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,download_status TEXT NOT NULL DEFAULT 'authorized');
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,reporter_id TEXT REFERENCES users(id),mod_id TEXT REFERENCES mods(id),reason TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS moderation_logs(id TEXT PRIMARY KEY,admin_id TEXT NOT NULL REFERENCES users(id),mod_id TEXT NOT NULL REFERENCES mods(id),action TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,message TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_activity_logs(id TEXT PRIMARY KEY,admin_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_mods_status_created ON mods(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_mods_category ON mods(category_id,status);
CREATE INDEX IF NOT EXISTS idx_downloads_mod ON downloads(mod_id,created_at);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
